def wrap(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")
    words = text.split()
    if not words:
        return []
    lines = []
    current = ""
    def add_piece(piece):
        nonlocal current
        if not current:
            current = piece
        else:
            if len(current) + 1 + len(piece) <= width:
                current = current + " " + piece
            else:
                lines.append(current)
                current = piece
    for w in words:
        i = 0
        while i < len(w):
            chunk = w[i:i+width]
            add_piece(chunk)
            i += width
    if current:
        lines.append(current)
    return lines

def run_tests():
    # expected examples
    tests = [
        ("the quick brown fox", 10, ["the quick", "brown fox"]),
        ("abcdefghij", 4, ["abcd", "efgh", "ij"]),
        ("", 5, []),
    ]
    all_passed = True
    for text, width, expected in tests:
        result = wrap(text, width)
        if result != expected:
            print(f"FAIL: wrap({text!r}, {width}) -> {result}, expected {expected}")
            all_passed = False
    # ValueError test
    try:
        wrap("a b", 0)
        print("FAIL: expected ValueError for width=0")
        all_passed = False
    except ValueError:
        pass
    # additional tests
    # single long word
    if wrap("abcdefgh", 3) != ["abc", "def", "gh"]:
        print("FAIL: wrap('abcdefgh', 3) test")
        all_passed = False
    # exact fit
    if wrap("a b c d", 5) != ["a b c", "d"]:
        print("FAIL: wrap('a b c d', 5) test")
        all_passed = False
    # spaces handling
    if wrap("  hello   world  ", 10) != ["hello", "world"]:
        print("FAIL: wrap('  hello   world  ', 10) test")
        all_passed = False
    if all_passed:
        print("ALL TESTS PASSED")
    else:
        print("SOME TESTS FAILED")

if __name__ == "__main__":
    run_tests()

